const titleScreen=document.getElementById('titleScreen');const titleBackground=[document.getElementById('loginScreen'),document.getElementById('signedIn')];titleBackground.forEach(el=>el.inert=true);document.getElementById('enterGame').onclick=()=>{titleScreen.hidden=true;titleBackground.forEach(el=>el.inert=false);const target=document.getElementById('loginScreen').hidden?document.getElementById('newGame'):document.getElementById('authId');target.focus();};
